package mz.bam.seeky.android;

import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.provider.OpenableColumns;import android.widget.*;import java.io.*;import java.util.*;

/** Local audio import and independent background gain, shared by playback and export snapshots. */
final class BackgroundSettings {
 static final int REQUEST=48;final ReaderActivity a;final SharedPreferences prefs;BackgroundSettings(ReaderActivity a){this.a=a;prefs=a.getSharedPreferences("reading_background",0);}
 String tr(String s){return AppLanguage.text(a,s);}
 void show(){UiPanel panel=new UiPanel(a,"Fundo de áudio",null,"audio");TextView name=a.text(prefs.getString("name",tr("Nenhum fundo escolhido")),14);panel.content.addView(name);TextView choose=a.button("Importar áudio de fundo",()->{panel.dialog.dismiss();try{a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("audio/*"),REQUEST);}catch(Exception e){toast(e.getMessage());}});UiBox.style(choose);panel.content.addView(choose);Switch enabled=new Switch(a);enabled.setText(tr("Usar na leitura por voz"));enabled.setTextColor(a.ink);enabled.setChecked(prefs.getBoolean("enabled",false));enabled.setEnabled(!prefs.getString("path","").isEmpty());enabled.setOnCheckedChangeListener((v,on)->{prefs.edit().putBoolean("enabled",on).apply();SpeechEvents.State state=SpeechEvents.state;BackgroundAudioService.follow(a,on&&state.active&&!state.paused);});panel.content.addView(enabled);TextView[] listen=new TextView[1];listen[0]=a.button(BackgroundAudioService.playing()?"Parar fundo":"Tocar durante a leitura",()->{if(BackgroundAudioService.playing()){BackgroundAudioService.stop(a);listen[0].setText(tr("Tocar durante a leitura"));}else{if(android.os.Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},47);BackgroundAudioService.play(a);listen[0].setText(tr("Parar fundo"));}});listen[0].setEnabled(!prefs.getString("path","").isEmpty());UiBox.style(listen[0]);panel.content.addView(listen[0]);TextView volume=a.text(tr("Volume do fundo")+" · "+prefs.getInt("volume",15)+"%",13);panel.content.addView(volume);SeekBar slider=new SeekBar(a);slider.setMax(100);slider.setProgress(prefs.getInt("volume",15));slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int p,boolean user){if(user){prefs.edit().putInt("volume",p).apply();volume.setText(tr("Volume do fundo")+" · "+p+"%");}}});panel.content.addView(slider);panel.content.addView(a.text("O fundo continua ao fechar este painel. Pode pará-lo aqui ou na notificação.",12));panel.show();}
 void result(int request,int result,Intent intent){if(request!=REQUEST||result!=Activity.RESULT_OK||intent==null||intent.getData()==null)return;Uri uri=intent.getData();toast("A importar fundo…");a.worker.execute(()->{File target=null;try{String name="Fundo";try(Cursor c=a.getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}File root=new File(a.getFilesDir(),"backgrounds");root.mkdirs();target=new File(root,UUID.randomUUID()+".audio");try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Áudio indisponível.");StudyFiles.copy(in,target,268435456L,()->a.dead);}if(target.length()==0)throw new IOException("O fundo está vazio.");prefs.edit().putString("path",target.getPath()).putString("name",name).putBoolean("enabled",true).apply();prune(a);a.ui(()->{toast("Fundo importado.");show();});}catch(Exception error){if(target!=null)target.delete();a.ui(()->toast(error.getMessage()));}});}
 static void prune(Context context){try{StorageReview.Protection keep=StorageReview.protection(context);File[] files=new File(context.getFilesDir(),"backgrounds").listFiles();if(files!=null)for(File file:files)if(file.getName().matches("[a-f0-9-]{36}\\.audio")&&!keep.keeps(file))file.delete();}catch(Exception error){AppDiagnostics.record(context,"background-cleanup-review",error);}}

 void toast(String s){Toast.makeText(a,tr(s==null?"Não foi possível importar o fundo.":s),Toast.LENGTH_LONG).show();}
}
